// Wraps edge-lexer: provides a tagsDef for known built-ins and a claimTag
// that classifies unknown tags by Edge convention. See docs/adr/0010 and
// docs/adr/0002.
//
// Convention: every unknown `@name(...)` is a component → a block tag
// that must be closed with `@end`. To use a component inline (without an
// `@end`), write `@!name(...)` — the `!` prefix tells edge-lexer to
// self-close the tag regardless of the `block: true` we return here.

import { Tokenizer } from 'edge-lexer'
import { BLOCK_TAGS, INLINE_TAGS } from './taxonomy.js'

function buildTagsDef() {
  const def = {}
  for (const name of BLOCK_TAGS) {
    def[name] = { block: true, seekable: true }
  }
  def.else = { block: false, seekable: false }
  def.elseif = { block: false, seekable: true }
  for (const name of INLINE_TAGS) {
    def[name] = { block: false, seekable: true }
  }
  return def
}

export function tokenize(source) {
  const tagsDef = buildTagsDef()

  const claimTag = (name) => {
    if (tagsDef[name]) return null
    // Unknown tag → component → block. If the author wrote `@!name(...)`,
    // edge-lexer's selfclosed flag overrides and the tag won't open a
    // block frame.
    return { block: true, seekable: true }
  }

  const tokenizer = new Tokenizer(source, tagsDef, {
    filename: 'template.edge',
    claimTag,
  })
  tokenizer.parse()
  return tokenizer.tokens
}
